local Singleton = import('Frame.Singleton')
local FileSyncer = CS.Engine.Lib.Updater.FileSyncer
local PathUtility = CS.Engine.Lib.PathUtility
local ResourceModule = CS.Engine.Modules.ResourceModule


---@class DownloaderMgr
---@field GetInstance fun(self:DownloaderMgr):DownloaderMgr
local DownloaderMgr = Class('DownloaderMgr', Singleton)

function DownloaderMgr:__init()
    self.tasks = {} ---下载队列
    self.runningTasks = {} ---下载中的列表
end

function DownloaderMgr:__delete()
    self.tasks = {}
    self.runningTasks = {}
end

function DownloaderMgr:Start(url, savePath, md5, expireDays, cb)
    if not table.find(self.tasks, function(v)
        return v.url == url
    end) and not self.runningTasks[tostring(url)] then
        table.insert(self.tasks, {url = url, savePath = savePath,
                                  md5 = md5,
                                  expireDays = expireDays, cb = cb})
    end
    self:_StartQueue()
end

function DownloaderMgr:_StartQueue()
    if #self.tasks > 0 and table.count(self.runningTasks) < 3 then
        local v = table.remove(self.tasks, 1)
        self.runningTasks[tostring(v.url)] = v
        local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductSplitPath)
        local url = v.url
        ---@type Engine.Lib.Updater.FileSyncer
        local syncer = FileSyncer(url, v.savePath, vendorPath, nil, true)
        syncer:SetFinishCallback(function(syncerV)
            self.runningTasks[tostring(url)] = nil
            if v.cb then
                v.cb(url)
            end
            self:_StartQueue() --开始下载下一个资源
        end)
        ---开始下载
        syncer:Start()
    end
end

return DownloaderMgr